"""docs/tools.md is generated by tools/tools_index.py: every tool is listed and the file is current."""
import subprocess, sys, unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


class ToolsIndex(unittest.TestCase):
    def test_index_is_current(self):
        done = subprocess.run([sys.executable, str(ROOT / 'tools/tools_index.py'), '--check'], capture_output=True, text=True)
        self.assertEqual(0, done.returncode, done.stdout + done.stderr)


if __name__ == '__main__':
    unittest.main()
